const http = require('node:http'); const { readFileSync } = require('node:fs'); http.createServer((request, response) => { const path = new URL(request.url, 'http://localhost').pathname === '/' ? 'index.html' : new URL(request.url, 'http://localhost').pathname.slice(1); try { response.setHeader('content-type', path.endsWith('.js') || path.endsWith('.mjs') ? 'text/javascript' : 'text/html'); response.end(readFileSync(path)); } catch { response.statusCode = 404; response.end('missing'); } }).listen(5173);
